// Program Group -> Set of LeetToGen categories it contains
export const GROUP_TO_LEET_MAP: Record<string, string[]> = {};
// Program Group -> Set of Top15 tags it contains
export const GROUP_TO_TOP15_MAP: Record<string, string[]> = {};
// Program Code -> ProgramDimension
export const CODE_TO_DIMENSION_MAP: Record<string, ProgramDimension> = {};

ALL_PROGRAM_DIMENSIONS.forEach((p) => {
  if (p.code) {
    CODE_TO_DIMENSION_MAP[p.code.toLowerCase()] = p;
  }
  if (p.group) {
    const grpUpper = p.group.toUpperCase();
    if (!GROUP_TO_LEET_MAP[grpUpper]) GROUP_TO_LEET_MAP[grpUpper] = [];
    if (p.leetToGen && !GROUP_TO_LEET_MAP[grpUpper].includes(p.leetToGen)) {
      GROUP_TO_LEET_MAP[grpUpper].push(p.leetToGen);
    }
    if (!GROUP_TO_TOP15_MAP[grpUpper]) GROUP_TO_TOP15_MAP[grpUpper] = [];
    if (p.top15 && !GROUP_TO_TOP15_MAP[grpUpper].includes(p.top15)) {
      GROUP_TO_TOP15_MAP[grpUpper].push(p.top15);
    }
  }
});

export function matchesLeetToGenFilter(
  nameOrCode: string,
  selectedCategories: string[]
): boolean {
  if (!selectedCategories || selectedCategories.length === 0) return true;
  const key = nameOrCode.toLowerCase();
  // Check direct program code
  if (CODE_TO_DIMENSION_MAP[key]) {
    return selectedCategories.includes(CODE_TO_DIMENSION_MAP[key].leetToGen);
  }
  // Check group name
  const grpUpper = nameOrCode.toUpperCase();
  if (GROUP_TO_LEET_MAP[grpUpper]) {
    return GROUP_TO_LEET_MAP[grpUpper].some((c) => selectedCategories.includes(c));
  }
  return true;
}

export function matchesTop15Filter(
  nameOrCode: string,
  selectedTop15: string
): boolean {
  if (!selectedTop15 || selectedTop15 === 'All') return true;
  const target = selectedTop15.toLowerCase();
  const key = nameOrCode.toLowerCase();
  
  if (CODE_TO_DIMENSION_MAP[key]) {
    return CODE_TO_DIMENSION_MAP[key].top15.toLowerCase().includes(target);
  }
  const grpUpper = nameOrCode.toUpperCase();
  if (GROUP_TO_TOP15_MAP[grpUpper]) {
    return GROUP_TO_TOP15_MAP[grpUpper].some((t) => t.toLowerCase().includes(target));
  }
  return true;
}
